-- 2026-11-14 CS-managed chat tiles (admin "Topics"). Additive only — no
-- existing table or column is dropped or rewritten.
--
-- 1. menu_tiles: the customer chat menu. Until this table has rows (or if it
--    cannot be read) the API falls back to data/menu_categories.json, so the
--    order of "apply migration" / "deploy API" does not matter.
--    labels        {"en": "...", "id": "...", "tl": "...", "ne": "...", "vi": "..."} (en required)
--    sub_questions {"en": ["..."], "vi": ["..."]}  (a missing language falls back to en)
--    id_prefixes   Rule ID topic codes whose rules the AI uses for this tile (GN = every tile)
--    kb_categories legacy kb_rules.category values (pre-CSV manuals; read-only in the admin)
--    scope_of      use another tile's knowledge range (e.g. connection → internet)
--    behavior      'free_text' for "Something else" (always last, cannot be disabled)
-- 2. menu_tile_change_log: who changed which tile, before/after (change history).
-- 3. Seed: the 12 tiles of data/menu_categories.json with the chat's 5-language
--    labels and sample questions, then fold the CS-added Topic codes links
--    (kb_topic_codes.topics) into the tiles' id_prefixes. kb_topic_codes is kept
--    (code names); its topics column is no longer read once tiles are in the DB.

create table if not exists menu_tiles (
  id text primary key check (id ~ '^[a-z][a-z0-9_]{1,31}$'),
  position integer not null,
  enabled boolean not null default true,
  icon text not null default 'ti-message-circle',
  labels jsonb not null default '{}'::jsonb,
  sub_questions jsonb not null default '{}'::jsonb,
  id_prefixes text[] not null default '{}',
  kb_categories text[] not null default '{}',
  scope_of text,
  behavior text not null default '',
  created_at timestamptz not null default now(),
  updated_by uuid references auth.users(id),
  updated_at timestamptz not null default now()
);

create table if not exists menu_tile_change_log (
  id serial primary key,
  tile_id text not null,
  action text not null,           -- create / update / reorder / enable / disable / link_codes
  changed_by uuid references auth.users(id),
  changed_at timestamptz not null default now(),
  before jsonb,
  after jsonb
);

-- Only the service role (the API) reads or writes them.
alter table menu_tiles enable row level security;
alter table menu_tile_change_log enable row level security;

