-- Fold the CS-added Topic codes links into the tiles (keeps every existing code).
update menu_tiles t
set id_prefixes = (
  select coalesce(array_agg(distinct x order by x), '{}')
  from unnest(
    t.id_prefixes || coalesce((select array_agg(c.code) from kb_topic_codes c where t.id = any(c.topics)), '{}')
  ) as x
)
where exists (select 1 from kb_topic_codes c where t.id = any(c.topics));
